import countriesData from '@/data/countries.json';
import indiaCitiesData from '@/data/india-cities.json';
import statesData from '@/data/states.json';

// Place lists for the country, state and city pickers. The data files are generated by
// scripts/build-places.mjs. We store plain names (not codes) on the profile, so these helpers
// translate a name to its code and back.

interface Place {
  code: string;
  name: string;
}

const countries: Place[] = countriesData;
const states = statesData as Record<string, Place[]>;
const indiaCities = indiaCitiesData as Record<string, string[]>;

// Lower-case and strip accents, so "Karnātaka" matches "Karnataka" when comparing names.
function simplify(text: string): string {
  return text.normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();
}

// Finds a place in a list by name, ignoring case and accents.
function findByName(list: Place[], name: string): Place | undefined {
  const wanted = simplify(name);
  return list.find((p) => simplify(p.name) === wanted);
}

// Every country name, A to Z.
export function countryNames(): string[] {
  return countries.map((c) => c.name);
}

// State or region names for a country. Empty when the country has none in our list.
export function stateNames(country: string): string[] {
  const code = findByName(countries, country)?.code;
  return code ? (states[code] ?? []).map((s) => s.name) : [];
}

// City names for a state. We only ship city lists for India; other countries return an empty
// list, and the screen lets the user type the city instead.
export function cityNames(country: string, state: string): string[] {
  const countryCode = findByName(countries, country)?.code;
  if (countryCode !== 'IN') return [];
  const stateCode = findByName(states.IN ?? [], state)?.code;
  return stateCode ? (indiaCities[stateCode] ?? []) : [];
}

// Matches a name from the phone's address lookup to our list, so it can fill the pickers.
// Returns the list's spelling, or the original text when there is no match.
export function matchCountry(name: string): string {
  return findByName(countries, name)?.name ?? name;
}

// Same as matchCountry, for a state inside a country.
export function matchState(country: string, name: string): string {
  const code = findByName(countries, country)?.code;
  return (code && findByName(states[code] ?? [], name)?.name) || name;
}
